package com.keyforge.nativeiiq.resource;
import com.keyforge.nativeiiq.model.*;import com.keyforge.nativeiiq.service.NativeWorkgroupMembershipExtractionService;import com.keyforge.nativeiiq.wire.NativeWorkgroupMembershipWire;import sailpoint.api.SailPointContext;import sailpoint.authorization.UnauthorizedAccessException;import sailpoint.rest.plugin.*;import javax.ws.rs.*;import javax.ws.rs.core.*;import java.util.Map;import java.util.logging.*;
@Path("keyForgeNativeIIQ") public class NativeWorkgroupMembershipResource extends BasePluginResource{private static final Logger LOG=Logger.getLogger(NativeWorkgroupMembershipResource.class.getName());public String getPluginName(){return "KeyForgeNativeIIQ";}@GET @Path("workgroup-memberships") @SystemAdmin @Produces(MediaType.APPLICATION_JSON) public Response get(@QueryParam("start") @DefaultValue("0") int start,@QueryParam("limit") @DefaultValue("100") int limit,@QueryParam("runId") String runId){int s=Math.max(0,start),l=limit<=0?100:Math.min(limit,500);String stage="context";try{SailPointContext c=getContext();stage="extract";NativeWorkgroupMembershipExtractionResult r=new NativeWorkgroupMembershipExtractionService().extract(c,s,l,runId);return Response.ok(NativeWorkgroupMembershipWire.envelope(r)).build();}catch(UnauthorizedAccessException e){LOG.log(Level.WARNING,"Native workgroup membership denied at "+stage,e);return Response.status(403).type(MediaType.APPLICATION_JSON).entity(NativeWorkgroupMembershipWire.error(403,e)).build();}catch(Throwable t){LOG.log(Level.SEVERE,"Native workgroup membership failed at "+stage,t);return Response.status(500).type(MediaType.APPLICATION_JSON).entity(NativeWorkgroupMembershipWire.error(500,t)).build();}}}
